package org.sleepwell.app;
import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.view.View;import android.widget.LinearLayout;
/** Explicit all-recording ZIP backup, separate from restorable metadata JSON. Never uploads automatically. */
public final class LibraryAudioExportActivity extends Activity implements LibraryAudioExportJob.Observer {
 private static final int SAVE=467;private LibraryAudioExportJob job;
 @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);Object retained=getLastNonConfigurationInstance();job=retained instanceof LibraryAudioExportJob?(LibraryAudioExportJob)retained:new LibraryAudioExportJob(getApplicationContext(),Records.factory,state!=null);job.observe(this);}
 @Override public Object onRetainNonConfigurationInstance(){return job;}
 public void changed(LibraryAudioExportJob.State state){if(isDestroyed())return;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Export audio library",this::finish);Design.space(body,16);Design.text(body,"A ZIP of every retained recording and its sound labels, favorites and recording provenance.",14,400,Design.MUTED);Design.space(body,16);if(state.plan!=null){Design.item(body,"wave","Complete recordings",""+state.plan.audio.size(),null);Design.item(body,"file","Sound events",""+state.plan.metadata.events.size(),null);Design.item(body,"moon","Source nights",""+state.plan.metadata.records.size(),null);Design.item(body,"upload","Uncompressed audio",android.text.format.Formatter.formatShortFileSize(this,state.plan.bytes),null);Design.space(body,12);}Design.text(body,"Complete audio may extend outside edited sleep times. Alarms, passwords and app credentials are excluded. Keep a separate JSON backup for record restore; this ZIP has no restore feature.",13,400,Design.MUTED);Design.space(body,14);if(!state.message.isEmpty())Design.text(body,state.message,14,500,state.phase==LibraryAudioExportJob.Phase.ERROR?0xffa93919:Design.BROWN);LinearLayout footer=RecordUi.footer(body);boolean ready=state.plan!=null&&!state.plan.audio.isEmpty()&&(state.phase==LibraryAudioExportJob.Phase.READY||state.phase==LibraryAudioExportJob.Phase.DONE);View choose=Design.button(footer,state.phase==LibraryAudioExportJob.Phase.WRITING?"Exporting…":"Choose ZIP save location",true,this::choose);RecordUi.enabled(choose,ready);if(state.phase==LibraryAudioExportJob.Phase.WRITING)Design.button(footer,"Cancel export",false,job::cancelExport);else if(state.phase!=LibraryAudioExportJob.Phase.LOADING&&state.phase!=LibraryAudioExportJob.Phase.CHOOSING&&state.phase!=LibraryAudioExportJob.Phase.CANCELLING)Design.button(footer,"Refresh contents review",false,job::refresh);if(state.phase==LibraryAudioExportJob.Phase.LOADING)Design.text(footer,"Checking the complete library…",13,400,Design.MUTED);}
 private void choose(){if(!job.choose())return;try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/zip").putExtra(Intent.EXTRA_TITLE,"SleepWell-audio-library.zip"),SAVE);}catch(android.content.ActivityNotFoundException unavailable){job.cancelChoice();SleepPicker.message(this,"No document picker","Enable Android Files to choose a ZIP destination.");}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=SAVE)return;if(result!=RESULT_OK||data==null||data.getData()==null)job.cancelChoice();else job.write(data.getData());}
 @Override protected void onDestroy(){job.detach(this);if(!isChangingConfigurations())job.close();super.onDestroy();}
 @Override protected void onPostResume(){super.onPostResume();RecordUi.lightBars(this);}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
